-- 2. CREACIÓN DE TABLAS Y ESQUEMAS
CREATE TABLE "inquilinos" (
    id SERIAL PRIMARY KEY,
    nombre VARCHAR NOT NULL,
    subdominio VARCHAR UNIQUE,
    estado_suscripcion VARCHAR DEFAULT 'active',
    nivel_plan VARCHAR DEFAULT 'free',
    creado_en VARCHAR,
    stripe_id_cliente VARCHAR,
    stripe_id_suscripcion VARCHAR,
    fin_suscripcion VARCHAR,
    fecha_ultimo_pago VARCHAR
);

CREATE TABLE "usuarios" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    nombre_usuario VARCHAR UNIQUE NOT NULL,
    nombre_completo VARCHAR,
    contrasena_encriptada VARCHAR NOT NULL,
    rol VARCHAR DEFAULT 'user'
);

CREATE TABLE "productos" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    nombre VARCHAR NOT NULL,
    codigo_barras VARCHAR,
    precio DOUBLE PRECISION NOT NULL,
    precio_costo DOUBLE PRECISION DEFAULT 0.0,
    cantidad INTEGER NOT NULL,
    inventario_minimo INTEGER DEFAULT 3,
    vendido INTEGER DEFAULT 0,
    fecha_entrada VARCHAR,
    imagen VARCHAR,
    clave_sat VARCHAR DEFAULT '01010101',
    clave_unidad_sat VARCHAR DEFAULT 'H87'
);

CREATE TABLE "variantes_producto" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    producto_id INTEGER REFERENCES "productos"(id) ON DELETE CASCADE,
    nombre VARCHAR NOT NULL,
    codigo_barras VARCHAR,
    precio_costo DOUBLE PRECISION,
    precio DOUBLE PRECISION,
    cantidad INTEGER NOT NULL,
    vendido INTEGER DEFAULT 0,
    clave_sat VARCHAR DEFAULT '01010101',
    clave_unidad_sat VARCHAR DEFAULT 'H87'
);

CREATE TABLE "notificaciones" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    mensaje VARCHAR NOT NULL,
    leido BOOLEAN DEFAULT FALSE
);

CREATE TABLE "turnos" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    usuario_id INTEGER NOT NULL,
    hora_inicio VARCHAR NOT NULL,
    hora_fin VARCHAR,
    efectivo_inicial DOUBLE PRECISION NOT NULL,
    efectivo_final_real DOUBLE PRECISION,
    efectivo_final_esperado DOUBLE PRECISION DEFAULT 0.0,
    diferencia DOUBLE PRECISION,
    estado VARCHAR DEFAULT 'open'
);

CREATE TABLE "movimientos_caja" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    turno_id INTEGER NOT NULL,
    tipo VARCHAR NOT NULL,
    monto DOUBLE PRECISION NOT NULL,
    motivo VARCHAR,
    creado_en VARCHAR NOT NULL
);

CREATE TABLE "perfiles_facturacion" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    rfc VARCHAR UNIQUE NOT NULL,
    razon_social VARCHAR NOT NULL,
    regimen_fiscal VARCHAR NOT NULL,
    codigo_postal VARCHAR NOT NULL,
    correo VARCHAR NOT NULL
);

CREATE TABLE "facturas" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    uuid VARCHAR UNIQUE NOT NULL,
    monto_total DOUBLE PRECISION NOT NULL,
    xml_url VARCHAR,
    pdf_url VARCHAR,
    creado_en VARCHAR NOT NULL,
    estado VARCHAR DEFAULT 'active'
);

CREATE TABLE "clientes" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    nombre VARCHAR NOT NULL,
    telefono VARCHAR,
    correo VARCHAR,
    limite_credito DOUBLE PRECISION DEFAULT 0.0,
    saldo_actual DOUBLE PRECISION DEFAULT 0.0
);

CREATE TABLE "pagos_cliente" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    cliente_id INTEGER REFERENCES "clientes"(id) ON DELETE CASCADE,
    turno_id INTEGER,
    usuario_id INTEGER REFERENCES "usuarios"(id) ON DELETE SET NULL,
    monto DOUBLE PRECISION NOT NULL,
    creado_en VARCHAR NOT NULL,
    notas VARCHAR
);

CREATE TABLE "devoluciones_producto" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    venta_id INTEGER NOT NULL,
    producto_id INTEGER NOT NULL,
    cantidad INTEGER NOT NULL,
    precio DOUBLE PRECISION NOT NULL,
    motivo VARCHAR,
    autorizado_por VARCHAR,
    creado_en VARCHAR NOT NULL
);

CREATE TABLE "historial_ventas" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    producto_id INTEGER NOT NULL,
    variante_id INTEGER,
    turno_id INTEGER,
    usuario_id INTEGER,
    cantidad INTEGER NOT NULL,
    precio_vendido DOUBLE PRECISION,
    precio_costo_vendido DOUBLE PRECISION DEFAULT 0.0,
    descuento DOUBLE PRECISION DEFAULT 0.0,
    metodo_pago VARCHAR DEFAULT 'efectivo',
    monto_efectivo DOUBLE PRECISION DEFAULT 0.0,
    monto_tarjeta DOUBLE PRECISION DEFAULT 0.0,
    creado_en VARCHAR NOT NULL,
    cancelado BOOLEAN DEFAULT FALSE,
    motivo_cancelacion VARCHAR,
    autorizado_por VARCHAR,
    factura_id INTEGER REFERENCES "facturas"(id) ON DELETE SET NULL,
    cliente_id INTEGER REFERENCES "clientes"(id) ON DELETE SET NULL
);

CREATE TABLE "configuraciones_tienda" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    nombre_tienda VARCHAR DEFAULT 'ABARROTES ED & E',
    rfc VARCHAR,
    telefono VARCHAR,
    correo VARCHAR,
    direccion VARCHAR,
    tasa_impuesto DOUBLE PRECISION DEFAULT 16.0,
    pie_ticket VARCHAR DEFAULT '¡Gracias por su compra!',
    logo_url VARCHAR,
    color_primario VARCHAR DEFAULT '#064E3B',
    color_secundario VARCHAR DEFAULT '#064E3B'
);

CREATE TABLE "proveedores" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    nombre VARCHAR NOT NULL,
    rfc VARCHAR,
    telefono VARCHAR,
    correo VARCHAR,
    direccion VARCHAR,
    notas VARCHAR
);

CREATE TABLE "compras" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    proveedor_id INTEGER REFERENCES "proveedores"(id) ON DELETE SET NULL,
    numero_factura VARCHAR,
    costo_total DOUBLE PRECISION DEFAULT 0.0,
    creado_en VARCHAR NOT NULL,
    notas VARCHAR,
    usuario_id INTEGER REFERENCES "usuarios"(id) ON DELETE SET NULL
);

CREATE TABLE "elementos_compra" (
    id SERIAL PRIMARY KEY,
    compra_id INTEGER REFERENCES "compras"(id) ON DELETE CASCADE,
    producto_id INTEGER NOT NULL,
    variante_id INTEGER,
    cantidad INTEGER NOT NULL,
    precio_costo DOUBLE PRECISION NOT NULL,
    precio DOUBLE PRECISION
);

CREATE TABLE "bitacora_usuarios" (
    id SERIAL PRIMARY KEY,
    inquilino_id INTEGER REFERENCES "inquilinos"(id) ON DELETE CASCADE,
    usuario VARCHAR,
    nombre_completo VARCHAR,
    rol VARCHAR,
    accion VARCHAR,
    detalles VARCHAR,
    fecha_hora VARCHAR
);

